/* ==UserStyle==
@name           Roblox - Zamlžení a Zlatý Diamant
@namespace      github.com/openstyles/stylus
@version        1.0.0
@description    Zamlžené panely s vlastním obrázkem na pozadí.
@author         Ty
==/UserStyle== */
@-moz-document domain("roblox.com") {
/* 2. Zamlžené rámečky, které přes ten obrázek propouští světlo */
    .navigation, 
    .rbx-header, 
    .section-content, 
    .game-card-container, 
    .card-item, 
    .profile-container, 
    .menu-secondary {
        
        /* Tmavá poloprůhledná barva */
        background: rgba(0, 0, 0, 0.4) !important; 
        
        /* Zamlžení obrázku pod rámečkem */
        backdrop-filter: blur(5px) !important; 
        -webkit-backdrop-filter: blur(5px) !important;
        
        /* Jemný okraj */
        border: 1px solid rgba(255, 255, 255, 0.1) !important; 
        border-radius: 8px !important;
    }/* Hlavní pozadí stránky */
    body {
        background-image: url('https://i.postimg.cc/cJ7yGT3y/SDOIJFHNEIOF.jpg') !important;
        background-size: cover !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
    }
}
